        {wake.supported && wake.held && <Badge tone="accent" className="hidden sm:inline-flex">Screen stays on</Badge>}
        <Button variant={handsFree ? "primary" : "secondary"} aria-pressed={handsFree} onClick={() => setHandsFree((v) => !v)}>
