      </div>
      <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-surface-2" aria-hidden>
        <div className="h-full bg-accent transition-[width]" style={{ width: `${((state.stepIndex + 1) / total) * 100}%` }} />
